async function clearQuery(){
  await options();const activeMode=await page.inputValue('#table-rule-mode'),clear=page.locator('#table-rules-clear');assert(['simple','grouped'].includes(activeMode));if(await clear.isEnabled())await clear.click();assert.equal(await clear.isDisabled(),true,'The actual Clear control confirms no active rule or rule error');assert.equal(await page.inputValue('#table-rule-mode'),activeMode);
  assert.equal(await page.locator('#table-rules li[data-table-rule-index]').count(),0);
  // Owner reset leaves old grouped markup hidden until the next grouped render.
  // Count the active rule subtree; inactive markup is not an accepted expression.
  if(activeMode==='simple')assert.equal(await page.locator('#table-expression-editor').isHidden(),true);else{assert.equal(await page.locator('#table-expression-editor').isVisible(),true);assert.equal(await page.locator('#table-expression-editor [data-expression-kind]').count(),0);}
  for(const id of['table-explorer-error','table-expression-error']){assert.equal(await page.locator('#'+id).isHidden(),true);assert.equal((await page.locator('#'+id).textContent()).trim(),'');}
  await page.fill('#table-search','');await page.selectOption('#table-filter','all');
}
